body.query:
query RepoQuery($owner: String!, $name: String!, $expression: String!) {
  repository(owner: $owner, name: $name) {
    id
    __typename
    ... {
      nameWithOwner
      description
      stargazerCount
      forkCount
      primaryLanguage {
        name
        color
      }
      pushedAt
      isPrivate
      isFork
      isArchived
    }
    homepageUrl
    watchers {
      totalCount
    }
    issues(states: [OPEN]) {
      totalCount
    }
    pullRequests(states: [OPEN]) {
      totalCount
    }
    closed_issues: issues(states: [CLOSED]) {
      totalCount
    }
    closed_pull_requests: pullRequests(states: [CLOSED, MERGED]) {
      totalCount
    }
    licenseInfo {
      name
      spdxId
    }
    repositoryTopics(first: 20) {
      totalCount
      nodes {
        topic {
          name
        }
      }
    }
    defaultBranchRef {
      name
      target {
        __typename
        ... on Commit {
          __typename
          ... {
            oid
            message
            committedDate
            author {
              name
              user {
                login
              }
            }
          }
          history(first: 0) {
            totalCount
          }
        }
      }
    }
    parent {
      nameWithOwner
    }
    viewerHasStarred
    viewerPermission
    hasIssuesEnabled
    hasDiscussionsEnabled
    hasWikiEnabled
    branch_count: refs(refPrefix: "refs/heads/") {
      totalCount
    }
    tag_count: refs(refPrefix: "refs/tags/") {
      totalCount
    }
    object(expression: $expression) {
      __typename
      ... on Tree {
        entries {
          name
          path
          type
          mode
          size
        }
      }
      ... on Blob {
        text
        isBinary
        byteSize
        isTruncated
      }
    }
  }
}
